mapper.insert:

    SELECT seq_cvpl_hstry.nextval FROM dual

INSERT INTO cvpl_hstry /* kr.or.ddit.domain.apt.complaint.mapper.ICvplMapper.insertCvplHstry */
            ( cvpl_hstry_id
              , cvpl_ans
              , pic_id
              , cvpl_reg_dt
              , cvpl_stts_cd
              , cvpl_no
    )VALUES( #{cvplHstryId}
              , #{cvplAns}
              , #{picId}
              , sysdate
              , #{cvplSttsCd}
              , #{cvplNo}
    )

mapper.select:
SELECT COUNT(*) /* kr.or.ddit.domain.apt.complaint.mapper.ICvplMapper.selectCvplCount */
FROM cvpl
WHERE user_no = #{userNo}
  AND apt_cmplex_no = #{aptCmplexNo}

SELECT * FROM (SELECT a.*, ROWNUM rnum FROM (SELECT /* kr.or.ddit.domain.apt.complaint.mapper.ICvplMapper.selectMyCvplList */ cvpl_no , cvpl_ty_cd , cvpl_loc , cvpl_cn , cvpl_stts_cd , cvpl_reg_dt , cvpl_mdf_dt , cvpl_rcpt_dt , cvpl_end_dt , cvpl_prrt , cvpl_file_no , cvpl_ttl , user_no , ho_no , apt_cmplex_no FROM cvpl WHERE user_no = #{searchVO.userNo} AND apt_cmplex_no = #{searchVO.aptCmplexNo} ORDER BY cvpl_reg_dt DESC) a
WHERE ROWNUM <= #{endRow}
) WHERE rnum >= #{startRow}

SELECT COUNT(*)
FROM cvpl
WHERE apt_cmplex_no = #{aptCmplexNo}

mapper.update:
UPDATE cvpl
   SET cvpl_stts_cd = 'CNCL'
 WHERE cvpl_no = #{cvplNo}
